    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following statements best reflects the ethical consensus on "Withholding" vs. "Withdrawing" life-sustaining treatment?', '["Withholding is allowed, but withdrawing is murder", "Withdrawing is allowed, but withholding is neglect", "There is no ethical or legal distinction between withholding and withdrawing a treatment that is no longer beneficial", "Withdrawing requires a court order, but withholding does not"]', 2, 'Ethicists and major medical organizations agree that if a treatment is no longer meeting the goals of care, it can be stopped, just as it could have been not started.'),
    (v_topic_id, 'A patient is being "Terminally Extubated." What is the primary goal of the medical team during this process?', '["To see if the patient can breathe on their own", "To ensure the patient is comfortable and free from respiratory distress using medications like opioids and benzodiazepines", "To speed up the death process", "To save the cost of the ventilator"]', 1, 'Terminal extubation is a comfort-focused procedure where the goal is a peaceful transition.'),
    (v_topic_id, 'Which class of medication is the "Gold Standard" for managing dyspnea (air hunger) during the withdrawal of mechanical ventilation?', '["Antibiotics", "Opioids (e.g., Morphine)", "Bronchodilators", "Diuretics"]', 1, 'Opioids are highly effective at reducing the sensation of breathlessness and providing comfort during the weaning or removal of a ventilator.'),
    (v_topic_id, 'Artificial Nutrition and Hydration (ANH) is ethically categorized as:', '["A basic human right that must never be stopped", "A medical intervention that can be withheld or withdrawn based on the same criteria as other life-prolonging treatments", "A type of comfort care", "Only for patients who can talk"]', 1, 'ANH (e.g., G-tubes, TPN) is considered a medical treatment, not "food and water" in the social sense, and can be declined.'),
    (v_topic_id, 'What is a "Time-Limited Trial" of therapy?', '["A way to save money", "An agreement to use a life-sustaining treatment (like dialysis or a ventilator) for a specific period to see if the patient improves, with a plan to stop if the goals are not met", "A randomized controlled trial", "None of the above"]', 1, 'Time-limited trials help bridge the gap between "doing everything" and "doing nothing" when the prognosis is uncertain.'),
    (v_topic_id, 'Which of the following is a potential "Harm" of artificial hydration in a dying patient?', '["Increased thirst", "Increased secretions (death rattle), pulmonary edema, and peripheral swelling", "Improved energy", "None of the above"]', 1, 'In the final stages of dying, the body cannot process fluids effectively, and hydration can often increase discomfort rather than relieve it.'),
    (v_topic_id, 'The "Rule of Double Effect" is often used to justify high-dose opioids at the end of life. What is the "Good Effect" and the "Foreseeable Bad Effect" in this context?', '["Good: Death; Bad: Pain", "Good: Pain relief; Bad: Respiratory depression/hastening of death", "Good: Hospital savings; Bad: Patient anger", "None of the above"]', 1, 'The clinician intends the pain relief; the potential for shortened life is an unintended but accepted side effect.'),
    (v_topic_id, 'How does "Palliative Sedation" differ from "Euthanasia"?', '["They are the same", "Palliative sedation uses medications to relieve suffering with the intent of comfort, whereas euthanasia uses medications with the specific intent of causing death", "Sedation is only for old people", "None of the above"]', 1, 'Intent, dosage titration, and the clinical context distinguish the two practices.'),
    (v_topic_id, 'In "Palliative Sedation to Unconsciousness" (PSU), the level of sedation is:', '["Always as high as possible", "Titrated to the minimum level required to achieve relief of the refractory symptom", "Determined by a judge", "None of the above"]', 1, 'Proportionality is key in palliative sedation.'),
    (v_topic_id, 'Which of the following is a "Refractory Symptom" that might justify palliative sedation?', '["Mild nausea", "Intractable pain or existential suffering that has failed all other palliative interventions", "A broken arm", "A cough"]', 1, 'Refractory means that standard therapies have been exhausted without success.'),
    (v_topic_id, 'A patient with end-stage dementia is "Not eating." The family is distressed and feels they are "Starving" the patient. The best response is:', '["Force-feed the patient", "Explain that loss of appetite is a natural part of the dying process and that force-feeding (via tube) does not improve comfort or survival in advanced dementia", "Tell the family to leave", "None of the above"]', 1, 'Providing emotional support and education about the pathophysiology of end-stage dementia is a core palliative task.'),
    (v_topic_id, 'Is it legally allowed to stop "Pacemaker" therapy at the end of life?', '["No, it''s a battery", "Yes, a pacemaker is a medical device and a patient or surrogate has the right to request its deactivation if it no longer aligns with the goals of care", "Only if it breaks", "None of the above"]', 1, 'Like any other intervention, an implanted device can be deactivated at the patient''s request.'),
    (v_topic_id, 'What is the role of an "AICD" (Automated Implantable Cardioverter Defibrillator) in a hospice patient?', '["It should always stay on", "It should typically be deactivated to prevent painful, unnecessary shocks as the patient naturally enters the dying process", "It should be removed surgically", "None of the above"]', 1, 'Defibrillators should be turned off to ensure a peaceful death without jarring, non-beneficial shocks.'),
    (v_topic_id, 'Which of the following describes "Terminal Weaning"?', '["Stopping all medication", "The gradual reduction of ventilator support (FIO2 and PEEP) to allow the patient to breathe on their own or die naturally", "Taking the patient for a walk", "None of the above"]', 1, 'This is an alternative to immediate extubation that may be preferred by some families.'),
    (v_topic_id, 'The "Principle of Proportionality" in sedation means:', '["The dose should be the same for everyone", "The treatment should be commensurate with the severity of the symptom being treated", "The sedation should be done in a large room", "None of the above"]', 1, 'Use only what is needed to achieve the goal.'),
    (v_topic_id, 'Does withdrawing a ventilator require "Brain Death"?', '["Yes", "No, life support can be withdrawn from any patient (competent or via surrogate) if it is determined to be non-beneficial or contrary to the patient''s wishes", "Only in some states", "None of the above"]', 1, 'Withdrawal is about the right to refuse care, not just the declaration of death.'),
    (v_topic_id, 'Which of the following is a "Common Myth" about stopping life support?', '["The patient will feel everything", "The doctor is giving up", "It is against all religions", "All of the above are common myths"]', 3, 'Myths often drive family anxiety and require careful, empathetic addressing by the medical team.'),
    (v_topic_id, 'In the context of EOL care, "Hydration" is often confused with "Comfort." Which of the following is true?', '["Dry mucous membranes (thirst) can be managed with good oral care (swabs, ice chips) rather than IV fluids", "IV fluids are the only way to treat thirst", "Patients die of thirst", "None of the above"]', 0, 'Symptom-targeted care (like oral hygiene) is often more effective than aggressive systemic interventions.'),
    (v_topic_id, 'Which of the following is an ethical "Safeguard" for palliative sedation?', '["It must be done in secret", "It should ideally involve an interdisciplinary review and clear documentation of the refractory nature of the symptoms", "The patient must be over 80", "None of the above"]', 1, 'Transparency and documentation protect both the patient and the clinicians.'),
    (v_topic_id, 'A "Time-Limited Trial" should include:', '["A specific clinical goal (e.g., improved oxygenation) and a specific timeframe (e.g., 48 hours)", "An open-ended commitment", "No family involvement", "None of the above"]', 0, 'Clarity on the "why" and "how long" is essential for the trial to be successful.'),
    (v_topic_id, 'Which of the following is a sign of "Respiratory Distress" during ventilator withdrawal?', '["Snoring", "Tachypnea, use of accessory muscles, and facial grimacing", "Increased appetite", "None of the above"]', 1, 'Clinical monitoring allows the team to titrate opioids effectively.'),
    (v_topic_id, 'The "Hastening of Death" via high-dose opioids is:', '["The primary goal", "A possible, but unintended, consequence of providing necessary comfort care (Double Effect)", "Illegal in all cases", "None of the above"]', 1, 'The ethical and legal framework focuses on the primary intent.'),
    (v_topic_id, 'When is it appropriate to "Refuse" a request for withdrawal of care?', '["If the doctor thinks it''s a bad idea", "Only if there is a legal dispute about the surrogate''s authority or the patient''s capacity", "Never", "None of the above"]', 1, 'Barring legal/capacity issues, the right to refuse care is nearly absolute.'),
    (v_topic_id, 'Which of the following "Supports" the patient during withdrawal of care?', '["Loud music", "Presence of family, spiritual support, and aggressive symptom management", "Continuous blood draws", "None of the above"]', 1, 'The environment should be optimized for a "good death."'),
    (v_topic_id, 'Does "Catholic" bioethics allow for the withdrawal of life support?', '["No", "Yes, if the treatment is considered ''extraordinary'' or ''burdensome'' and does not offer a reasonable hope of benefit", "Only for old people", "None of the above"]', 1, 'Most major religions have nuanced frameworks that distinguish between killing and "allowing to die."'),
    (v_topic_id, 'A "G-Tube" (Gastrostomy Tube) is considered:', '["Medical treatment", "Standard food", "An ornament", "None of the above"]', 0, 'Like a ventilator, it is a technological intervention.'),
    (v_topic_id, 'Which of the following describes "Terminal Restlessness"?', '["A patient wanting to go for a run", "Agitation, confusion, and picking at sheets in the final days of life, often requiring sedation for comfort", "Insomnia", "None of the above"]', 1, 'It can be very distressing for families and requires pharmacologic management.'),
    (v_topic_id, 'What is the "First Line" medication for terminal restlessness?', '["Morphine", "Benzodiazepines (e.g., Midazolam) or Neuroleptics (e.g., Haloperidol)", "Caffeine", "None of the above"]', 1, 'Sedatives/neuroleptics target the neurological agitation.'),
    (v_topic_id, 'Which of the following is a benefit of "Home Death" for some patients?', '["Better equipment", "Familiarity, privacy, and control over the environment", "Free medication", "None of the above"]', 1, 'Most patients express a preference to die at home.'),
    (v_topic_id, 'A "Physician-Assisted Death" (PAD) is different from withdrawal of care because:', '["PAD involves an active injection by the doctor", "PAD involves the patient self-administering a lethal medication provided by the doctor, whereas withdrawal is removing a life-sustaining treatment", "They are the same", "None of the above"]', 1, 'PAD is the term used in legal jurisdictions for what was formerly called PAS.'),
    (v_topic_id, 'Can "Dialysis" be stopped?', '["No, it''s essential", "Yes, it is a burdensome life-sustaining treatment that can be withdrawn at any time if it no longer meets the goals of care", "Only if the kidneys start working", "None of the above"]', 1, 'Dialysis withdrawal is a common transition to hospice.'),
    (v_topic_id, 'The "Moral Difference" between killing and letting die is:', '["There is none", "Killing is an act that initiates a new death-causing chain, whereas letting die is allowing an underlying disease process to run its natural course", "Letting die is worse", "None of the above"]', 1, 'This distinction is fundamental to clinical ethics.'),
    (v_topic_id, 'Which of the following is a "Common Side Effect" of opioids at the end of life?', '["Diarrhea", "Constipation", "Hyperactivity", "None of the above"]', 1, 'Managing side effects is part of palliative excellence.'),
    (v_topic_id, 'What is "Palliative Sedation to Unconsciousness" (PSU) also called?', '["Slow code", "Continuous Deep Sedation", "Assisted suicide", "None of the above"]', 1, 'The term emphasizes the continuous nature of the sedation until death.'),
    (v_topic_id, 'Does "Hospice" allow for the use of IV fluids?', '["Never", "Yes, in some cases if the patient/family wants them for comfort, though they are usually discouraged if not beneficial", "Only in the hospital", "None of the above"]', 1, 'Hospice is about goals, not a list of "banned" treatments, though the focus remains on comfort.'),
    (v_topic_id, 'The "Goal" of palliative sedation is to:', '["Kill the patient", "Relieve refractory suffering", "Save money", "None of the above"]', 1, 'The intent is relief.'),
    (v_topic_id, 'Which of the following "Supports" the Rule of Double Effect?', '["The bad effect is not the means to the good effect", "The clinician has no choice", "The patient is old", "None of the above"]', 0, 'This is one of the four requirements of the classic Rule of Double Effect.'),
    (v_topic_id, 'A patient "Stop breathing" immediately after a dose of morphine during ventilator withdrawal. The doctor should:', '["Give Narcan (Naloxone)", "Recognize this as a possible outcome of the comfort care process and support the family through the transition", "Call the police", "None of the above"]', 1, 'Narcan would cause a "pain crisis" and defeat the purpose of comfort care.'),
    (v_topic_id, 'Which of the following is NOT a form of "Artificial Nutrition"?', '["TPN (Total Parenteral Nutrition)", "NG-tube (Nasogastric tube)", "Spoon-feeding by a nurse", "G-tube (Gastrostomy tube)"]', 2, 'Spoon-feeding (assisted oral feeding) is NOT a medical intervention and should be continued as long as safe and tolerated.'),
    (v_topic_id, 'What is "Comfort Care Only" (CCO)?', '["A type of insurance", "A set of medical orders focusing entirely on symptom management and quality of life rather than life-prolonging treatments", "No care at all", "None of the above"]', 1, 'CCO is a comprehensive goal-oriented status.'),
    (v_topic_id, 'A "Lethal Injection" given by a doctor is:', '["Euthanasia", "Palliative Sedation", "PAS", "None of the above"]', 0, 'Euthanasia involves the doctor acting directly to cause death.'),
    (v_topic_id, 'Which of the following is a "Legal Protections" for doctors providing EOL care?', '["None", "State laws and ethical consensus generally protect clinicians who follow a patient''s valid directive or surrogate instructions in good faith", "Doctors can do whatever they want", "None of the above"]', 1, 'Good faith adherence to established standards is a strong legal defense.'),
    (v_topic_id, 'The "Burden" of treatment refers to:', '["The cost in dollars", "The physical, psychological, and spiritual toll the treatment takes on the patient compared to its benefits", "The weight of the machine", "None of the above"]', 1, 'Assessing the "Burden/Benefit Ratio" is central to EOL decision making.'),
    (v_topic_id, 'What is the "Dying Process"?', '["A 5-minute event", "The final stage of life where physiological systems gradually shut down, which can take hours or days", "Something that only happens in the ICU", "None of the above"]', 1, 'Understanding death as a process helps in managing family expectations.'),
    (v_topic_id, 'Which of the following is a "Sign of Death" (Circulatory)?', '["Sleeping", "Absence of pulse, heart sounds, and respirations for a period of observation", "Closed eyes", "None of the above"]', 1, 'This is the traditional definition of death.'),
    (v_topic_id, 'A "Do Not De-escalate" order might be used when:', '["The family is undecided", "The patient is currently stable but the team agrees not to add any new aggressive interventions (e.g., ''Do Not Add Vasopressors'')", "The doctor is leaving", "None of the above"]', 1, 'This is part of "step-wise" EOL planning.'),
    (v_topic_id, 'Which of the following is "Essential" for a nurse during withdrawal of care?', '["To be a robot", "Clear communication with the physician and family, and the authority to titrate comfort medications within a specified range", "To hide the medications", "None of the above"]', 1, 'Nurses are the primary "comfort providers" during the dying process.'),
    (v_topic_id, 'The "Hastening of death" is ethically acceptable if:', '["The doctor is in a hurry", "It is an unintended side effect of necessary pain relief (Double Effect)", "The patient is annoying", "None of the above"]', 1, 'This is the standard ethical line.'),
    (v_topic_id, 'What is "Spiritual Anguish"?', '["A type of headache", "Severe distress related to questions of meaning, guilt, or the afterlife in a dying patient", "Hunger", "None of the above"]', 1, 'Addressing spiritual needs is part of holistic palliative care.'),
    (v_topic_id, 'Which of the following is a "Reason" to use Palliative Sedation?', '["To free up a bed", "To relieve refractory, agonizing symptoms that have not responded to any other treatment", "To end the life of a patient who is ''tired", "None of the above"]', 1, 'Relief of suffering is the ONLY valid reason.')
